contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint firstVal, uint secondVal) public {
        bool firstReverted;
        c.SetMinSum(firstVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        uint minSumAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(secondVal); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }

        uint minSumAfterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            firstReverted ||
            (
                !firstReverted &&
                !secondReverted &&
                minSumAfterFirst == firstVal &&
                minSumAfterSecond == secondVal
            )
        );
    }
}

